import { beforeEach, describe, expect, it, vi } from 'vitest';

// 16-S2 acceptance (16-S2-9): setPuzzleVisibility, against an in-memory store
// that applies Prisma's where semantics and, like `@updatedAt`, stamps
// `updatedAt` on every write that doesn't set it. Unsupported queries, raw SQL
// and any play-session access throw. Never a database connection.
// Do not edit this file to match an implementation.

const mocks = vi.hoisted(() => ({
  requireSession: vi.fn(), revalidatePath: vi.fn(), unsupported: vi.fn(),
  puzzle: { findUnique: vi.fn(), findFirst: vi.fn(), update: vi.fn(), updateMany: vi.fn() },
}));
vi.mock('@/lib/require-session', () => ({ requireSession: mocks.requireSession }));
vi.mock('next/cache', () => ({ revalidatePath: mocks.revalidatePath }));
vi.mock('@/lib/prisma', () => {
  const unsupported = (name: string) => (...args: unknown[]) => {
    mocks.unsupported(name, ...args);
    throw new Error(`unsupported in this store: ${name}`);
  };
  const puzzle = new Proxy(mocks.puzzle as Record<string, unknown>, {
    get: (target, key: string) => target[key] ?? unsupported(`puzzle.${key}`),
  });
  const playSession = new Proxy({}, { get: (_target, key: string) => unsupported(`playSession.${key}`) });
  const prisma: Record<string, unknown> = {
    puzzle, playSession,
    $executeRaw: unsupported('$executeRaw'), $executeRawUnsafe: unsupported('$executeRawUnsafe'),
    $queryRaw: unsupported('$queryRaw'), $queryRawUnsafe: unsupported('$queryRawUnsafe'),
  };
  prisma.$transaction = async (arg: unknown) => {
    if (typeof arg === 'function') return (arg as (tx: unknown) => unknown)(prisma);
    return Promise.all(arg as Promise<unknown>[]);
  };
  return { prisma };
});
import { setPuzzleVisibility } from './actions';

type Row = Record<string, unknown>;

const CALLER = 'builder-a';
const OTHER = 'builder-b';
const STAMP = new Date('2030-01-01T00:00:00Z');

let puzzles: Row[];

function puzzle(id: string, builderId: string, state: 'grid' | 'hints' | 'private' | 'public'): Row {
  const row: Row = {
    id, builderId, title: `Title ${id}`,
    grid: { cols: 1, rows: 1, cells: [[{ kind: 'active', letter: 'A' }]] },
    gridBeforeHints: state === 'grid' ? null : { cols: 1, rows: 1, cells: [[{ kind: 'active', letter: null }]] },
    hints: { '1-across': 'Clue' },
    phase: state === 'grid' ? 'grid' : 'hints',
    publishedAt: state === 'private' || state === 'public' ? new Date('2026-01-02T03:04:05Z') : null,
    visibility: state === 'public' ? 'public' : 'private',
    createdAt: new Date('2026-01-01T00:00:00Z'),
    updatedAt: new Date('2026-01-03T00:00:00Z'),
  };
  puzzles.push(row);
  return row;
}

function same(a: unknown, b: unknown) {
  return a instanceof Date && b instanceof Date ? a.getTime() === b.getTime() : a === b;
}

/** Prisma's where semantics for the scalar filters a guarded write can use. */
function matches(row: Row, where: Row | undefined): boolean {
  if (!where) return true;
  return Object.entries(where).every(([key, expected]) => {
    if (key === 'AND') return ([] as Row[]).concat(expected as Row | Row[]).every((clause) => matches(row, clause));
    if (key === 'OR') return (expected as Row[]).some((clause) => matches(row, clause));
    if (key === 'NOT') return !([] as Row[]).concat(expected as Row | Row[]).some((clause) => matches(row, clause));
    if (!(key in row)) throw new Error(`unsupported filter: ${key}`);
    const actual = row[key];
    if (expected === null || expected instanceof Date || typeof expected !== 'object') return same(actual, expected);
    return Object.entries(expected as Row).every(([op, value]) => {
      if (op === 'equals') return same(actual, value);
      if (op === 'not') return value === null ? actual !== null : !same(actual, value);
      if (op === 'in') return (value as unknown[]).some((v) => same(actual, v));
      if (op === 'notIn') return !(value as unknown[]).some((v) => same(actual, v));
      throw new Error(`unsupported operator: ${key}.${op}`);
    });
  });
}

function project(row: Row, select: Record<string, unknown> | undefined) {
  if (!select) return structuredClone(row);
  return Object.fromEntries(Object.keys(select).filter((key) => select[key]).map((key) => {
    if (!(key in row)) throw new Error(`unsupported select: ${key}`);
    return [key, structuredClone(row[key])];
  }));
}

function write(row: Row, data: Row) {
  for (const key of Object.keys(data)) if (!(key in row)) throw new Error(`unsupported field: ${key}`);
  Object.assign(row, structuredClone(data));
  if (!('updatedAt' in data)) row.updatedAt = STAMP;
}

/** Everything but visibility, deep-copied. */
function rest(row: Row) {
  const others = structuredClone(row);
  delete others.visibility;
  return others;
}

beforeEach(() => {
  vi.resetAllMocks();
  puzzles = [];
  mocks.requireSession.mockResolvedValue({ user: { id: CALLER }, session: { id: 'valid' } });
  mocks.puzzle.findUnique.mockImplementation(async ({ where, select }: { where: Row; select?: Row }) => {
    const found = puzzles.find((row) => matches(row, where));
    return found ? project(found, select) : null;
  });
  mocks.puzzle.findFirst.mockImplementation(async ({ where, select }: { where: Row; select?: Row }) => {
    const found = puzzles.find((row) => matches(row, where));
    return found ? project(found, select) : null;
  });
  mocks.puzzle.updateMany.mockImplementation(async ({ where, data }: { where: Row; data: Row }) => {
    const hit = puzzles.filter((row) => matches(row, where));
    for (const row of hit) write(row, data);
    return { count: hit.length };
  });
  mocks.puzzle.update.mockImplementation(async ({ where, data, select }: { where: Row; data: Row; select?: Row }) => {
    const found = puzzles.find((row) => matches(row, where));
    if (!found) throw Object.assign(new Error('Record to update not found.'), { code: 'P2025' });
    write(found, data);
    return project(found, select);
  });
});

describe('16-S2-9 setPuzzleVisibility', () => {
  it('makes the caller’s unlisted puzzle public and back, changing nothing else, updatedAt included', async () => {
    const own = puzzle('own', CALLER, 'private');
    const before = rest(own);

    await expect(setPuzzleVisibility('own', 'public')).resolves.toEqual({ visibility: 'public' });
    expect(own.visibility).toBe('public');
    expect(rest(own)).toEqual(before);

    await expect(setPuzzleVisibility('own', 'private')).resolves.toEqual({ visibility: 'private' });
    expect(own.visibility).toBe('private');
    expect(rest(own)).toEqual(before);
    expect(mocks.revalidatePath).toHaveBeenCalledWith('/puzzles');
  });

  it('choosing the current visibility succeeds and changes nothing', async () => {
    const own = puzzle('own', CALLER, 'public');
    const before = structuredClone(own);
    await expect(setPuzzleVisibility('own', 'public')).resolves.toEqual({ visibility: 'public' });
    expect(own).toEqual(before);
  });

  it('refuses an unpublished puzzle, another builder’s and a missing one, changing nothing', async () => {
    puzzle('draft', CALLER, 'grid');
    puzzle('hinting', CALLER, 'hints');
    puzzle('theirs-unlisted', OTHER, 'private');
    puzzle('theirs-public', OTHER, 'public');
    const before = structuredClone(puzzles);

    for (const [id, value] of [
      ['draft', 'public'], ['hinting', 'public'],
      ['theirs-unlisted', 'public'], ['theirs-public', 'private'],
      ['missing', 'public'],
    ] as const) {
      await expect(setPuzzleVisibility(id, value), id).rejects.toThrow();
    }
    expect(puzzles).toEqual(before);
  });

  it('rejects any other value before touching the database', async () => {
    const own = puzzle('own', CALLER, 'private');
    const before = structuredClone(own);
    for (const value of ['unlisted', 'Public', 'PRIVATE', '', null, undefined, 1, {}]) {
      await expect(setPuzzleVisibility('own', value as never), String(value)).rejects.toThrow();
    }
    for (const method of Object.values(mocks.puzzle)) expect(method).not.toHaveBeenCalled();
    expect(own).toEqual(before);
  });

  it('requires a session before touching the database', async () => {
    puzzle('own', CALLER, 'private');
    mocks.requireSession.mockRejectedValue(new Error('redirect:/'));
    await expect(setPuzzleVisibility('own', 'public')).rejects.toThrow();
    for (const method of Object.values(mocks.puzzle)) expect(method).not.toHaveBeenCalled();
    expect(mocks.revalidatePath).not.toHaveBeenCalled();
  });

  it('never reads or writes play sessions, and uses no raw SQL', async () => {
    puzzle('own', CALLER, 'private');
    await setPuzzleVisibility('own', 'public');
    expect(mocks.unsupported).not.toHaveBeenCalled();
  });
});
